		effect,
		get: (options) => Effect.runPromise(effect(options)),
		reset: () =>
			Effect.suspend(() => {
				hasLoadedValue = false;
				generation += 1;
				const fiber = inFlight?.fiber;
				inFlight = undefined;
				return (
					fiber ? Effect.asVoid(Fiber.interrupt(fiber)) : Effect.void
