					Effect.andThen(
						Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY),
					),
					Effect.asVoid,
				);
			}),
		close: () =>
			Effect.suspend(() => {
				const fiber = inFlight?.fiber;
				inFlight = undefined;
				return fiber ? Effect.asVoid(Fiber.interrupt(fiber)) : Effect.void;
			}),
